"use client";

import { useEffect } from "react";
import { animate, type AnimationOptions, type DOMKeyframesDefinition } from "motion";
import "./component-demos.css";

type DemoName = keyof typeof demoPositions;
type MotionState = Record<string, unknown> & { transition?: Record<string, unknown> };
type AuthTour = {
  timings: Record<string, number>;
  targets: { tag: string; className: string; index: number; initial?: MotionState; transition?: Record<string, unknown>; states: Record<string, MotionState> }[];
};

type AdvancedTour = {
  timings: Record<string, number>;
  templates: number[];
  frames: Record<string, {
    template: number;
    animations: Record<string, { initial: MotionState; animate: MotionState; transition: Record<string, unknown> }>;
  }>;
};

const demoPositions = {
  UserButton: [184, 931, 368, 649],
  UserProfile: [0, 1411, 368, 1214.5],
  CreateOrganization: [184, 1852, 368, 1641],
  PricingTable: [552, 589, 736, 489],
  Waitlist: [552, 1051, 736, 951],
  SignUp: [552, 1592, 736, 1592],
  SignIn: [552, 2194, 736, 2094],
  OrganizationSwitcher: [920, 829, 1104, 689],
  OrganizationProfile: [1104, 1307, 1104, 974],
  OrganizationList: [920, 1800, 1104, 1534],
} as const;

const foregroundOrder: DemoName[] = [
  "UserButton", "UserProfile", "CreateOrganization", "PricingTable", "Waitlist",
  "SignUp", "SignIn", "OrganizationSwitcher", "OrganizationProfile", "OrganizationList",
];

const imagePaths: [DemoName, number[]][] = [
  ["UserButton", [0, 1, 1]], ["UserButton", [0, 1, 2]],
  ["UserProfile", [0, 2]], ["UserProfile", [0, 3]],
  ["CreateOrganization", [0, 5, 0]],
  ["PricingTable", [1, 1]], ["Waitlist", [1, 2]],
  ["SignUp", [1, 3]], ["SignIn", [1, 4]],
  ["OrganizationSwitcher", [2, 0, 2]],
  ["OrganizationProfile", [2, 2]], ["OrganizationProfile", [2, 3]],
  ["OrganizationList", [2, 4, 0]],
];

function atPath(root: HTMLElement, path: number[]) {
  let node: Element | undefined = root;
  for (const index of path) node = node?.children[index];
  return node instanceof HTMLElement ? node : null;
}

function componentName(button: HTMLButtonElement): DemoName | null {
  const name = button.textContent?.match(/<([A-Za-z]+)\s*\/>/)?.[1];
  return name && name in demoPositions ? name as DemoName : null;
}

export function ComponentDemos() {
  useEffect(() => {
    const root = document.getElementById("components");
    if (!root) return;

    const originalAttributes = new Map<Element, [string, string][]>();
    const remember = (element: Element | null) => {
      if (element && !originalAttributes.has(element)) {
        originalAttributes.set(element, Array.from(element.attributes, ({ name, value }) => [name, value]));
      }
    };
    const addClass = (element: Element, className: string) => {
      remember(element);
      element.classList.add(className);
    };
    const listen = (element: EventTarget, event: string, callback: EventListener) => {
      element.addEventListener(event, callback);
      cleanups.push(() => element.removeEventListener(event, callback));
    };
    const cleanups: (() => void)[] = [];
    const tracks = Array.from(root.querySelectorAll<HTMLElement>('.font-mosaic [style*="--x:"]'));
    const maskTrack = tracks[0];
    const foregroundTrack = tracks[1];
    if (!maskTrack || !foregroundTrack) return;
    remember(root);
    root.dataset.sdkControl = "";

    const triggers = Array.from(root.querySelectorAll<HTMLButtonElement>('button[slot="trigger"][aria-controls]'));
    const disclosures = triggers.flatMap(trigger => {
      const panel = document.getElementById(trigger.getAttribute("aria-controls") || "");
      if (!panel || !root.contains(panel)) return [];
      const buttons = Array.from(panel.querySelectorAll<HTMLButtonElement>("li button"));
      [trigger, panel, trigger.parentElement?.parentElement, trigger.querySelector("span"), trigger.querySelector("svg")].forEach(node => remember(node || null));
      buttons.forEach(button => {
        remember(button);
        const icon = button.querySelector("span.flex");
        remember(icon);
      });
      addClass(panel, "aurora-demo-disclosure");
      panel.removeAttribute("hidden");
      panel.inert = trigger.getAttribute("aria-expanded") !== "true";
      return [{ trigger, panel, buttons }];
    });

    imagePaths.forEach(([name, path]) => {
      const card = atPath(maskTrack, path);
      if (card) {
        remember(card);
        card.dataset.demoImage = name;
      }
    });

    // Small screens use the captured image cards and the same mosaic coordinates.
    const mobileTrack = maskTrack.cloneNode(true) as HTMLElement;
    mobileTrack.classList.add("aurora-demo-mobile-track");
    mobileTrack.removeAttribute("inert");
    mobileTrack.querySelectorAll<HTMLImageElement>("img").forEach(img => {
      if (img.closest("[data-demo-image]")) return;
      const placeholder = img.parentElement;
      if (placeholder) placeholder.style.aspectRatio = `${img.width} / ${img.height}`;
      img.remove();
    });
    foregroundTrack.parentElement?.append(mobileTrack);
    addClass(foregroundTrack, "aurora-demo-desktop-track");
    cleanups.push(() => mobileTrack.remove());
    tracks.push(mobileTrack);
    tracks.forEach(track => {
      remember(track);
      track.dataset.demoTrack = "";
    });

    const scaleContainers = Array.from(foregroundTrack.querySelectorAll<HTMLElement>('[style*="--scale:"]'));
    const foregroundCards = scaleContainers.flatMap((container, index) => {
      const card = container.querySelector<HTMLElement>('[role="presentation"]');
      if (!card || !foregroundOrder[index]) return [];
      remember(container);
      remember(card);
      card.dataset.demoCard = foregroundOrder[index];
      return [{ card, name: foregroundOrder[index] }];
    });
    [atPath(foregroundTrack, [0, 2]), atPath(foregroundTrack, [2, 2])].forEach((card, index) => {
      if (!card) return;
      remember(card);
      card.dataset.demoCard = index === 0 ? "UserProfile" : "OrganizationProfile";
    });

    const initialCard = foregroundCards.find(({ name }) => name === "SignUp")?.card;
    const glowNodes = initialCard ? Array.from(initialCard.children).filter(node => node.classList.contains("-inset-4") || node.classList.contains("-inset-8")) : [];
    const mobileGlow = glowNodes.find(node => node.classList.contains("-inset-4"))?.cloneNode(true) as HTMLElement | undefined;
    cleanups.push(() => {
      if (initialCard) initialCard.prepend(...glowNodes);
      mobileGlow?.remove();
    });

    const scaleCards = () => {
      scaleContainers.forEach(container => {
        const child = container.firstElementChild as HTMLElement | null;
        const width = parseFloat(child?.style.width || "");
        if (width && container.clientWidth) container.style.setProperty("--scale", String(container.clientWidth / width));
      });
    };
    const resizeObserver = new ResizeObserver(scaleCards);
    scaleContainers.forEach(container => resizeObserver.observe(container));
    cleanups.push(() => resizeObserver.disconnect());
    scaleCards();

    let selectedDemo: DemoName = "SignUp";
    let inView = false;
    const smallScreen = window.matchMedia("(max-width: 768px)");
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const runningAnimations = new Set<{ stop: () => void }>();
    const motionTo = (element: Element, state: MotionState, defaults: Record<string, unknown> = {}) => {
      const { transition, ...properties } = state;
      const options = { ...defaults, ...transition } as AnimationOptions;
      if (typeof properties.duration === "number") {
        options.duration = properties.duration;
        delete properties.duration;
      }
      if (reducedMotion.matches) {
        options.duration = 0;
        options.delay = 0;
        options.type = "tween";
      }
      const controls = animate(element, properties as DOMKeyframesDefinition, options);
      runningAnimations.add(controls);
      controls.then(() => runningAnimations.delete(controls));
    };
    const basicTours = foregroundCards.flatMap(({ card, name }) => {
      const spec = authTours[name];
      if (!spec) return [];
      const states = Object.keys(spec.timings);
      const targets = spec.targets.flatMap(target => {
        // The two inline arrow SVGs are scoped to the submit control.
        const candidates = Array.from(card.querySelectorAll<HTMLElement | SVGElement>(target.tag)).filter(element => (element.getAttribute("class") || "") === target.className);
        let element = candidates[target.index];
        if (target.tag === "svg" && !target.className) {
          const submit = card.querySelector<HTMLElement>('div[class*="bg-gray-800"][class*="justify-center"]');
          const arrows = submit?.querySelectorAll<SVGElement>("svg");
          element = arrows?.[target.index - 2] || element;
        }
        if (!element) return [];
        remember(element);
        return [{ ...target, element, last: "" }];
      });
      const fields = Array.from(card.querySelectorAll<HTMLElement>("span.relative.whitespace-pre, span.relative.min-w-1")).map(field => {
        const originals = Array.from(field.childNodes);
        const caret = field.querySelector<HTMLElement>('span[class*="top-[0.1em]"]');
        const text = document.createTextNode("");
        remember(field);
        field.style.color = "#19191B";
        return { field, originals, caret, text };
      });
      const cursor = card.querySelector<HTMLElement>(':scope > .absolute.inset-0.z-50 > .will-change-transform');
      const cursorIcon = cursor?.querySelector<SVGElement>("svg");
      remember(cursor);
      remember(cursorIcon || null);
      const cursorSpec = authCursorTours[name];
      let stateIndex = 0;
      let timer: ReturnType<typeof setTimeout> | null = null;
      const typingTimers = new Set<ReturnType<typeof setTimeout>>();
      let initialized = false;
      const clearTyping = () => {
        typingTimers.forEach(clearTimeout);
        typingTimers.clear();
      };
      const typeField = (index: number, value: string) => {
        const field = fields[index];
        if (!field) return;
        field.field.replaceChildren(field.text, ...(field.caret ? [field.caret] : []));
        field.text.textContent = "";
        Array.from(value).forEach((_, position) => {
          const typingTimer = setTimeout(() => {
            field.text.textContent = value.slice(0, position + 1);
            typingTimers.delete(typingTimer);
          }, position * 50);
          typingTimers.add(typingTimer);
        });
      };
      const update = () => {
        const state = states[stateIndex];
        targets.forEach(target => {
          const applicable = states.slice(0, stateIndex + 1).reverse().find(key => key in target.states);
          if (!applicable) return;
          const value = target.states[applicable];
          const serialized = JSON.stringify(value);
          if (serialized === target.last) return;
          target.last = serialized;
          motionTo(target.element, value, target.transition);
        });
        if (cursor && cursorSpec) {
          const position = cursorSpec.positions[state];
          if (position) motionTo(cursor, { transform: position }, { duration: 0.6, ease: [0.22, 1, 0.36, 1], delay: state === "reset" ? 0.5 : 0 });
          if (cursorIcon && /^(focus|click)/.test(state)) motionTo(cursorIcon, { transform: ["scale(1)", "scale(0.85)", "scale(1)"] }, { duration: 0.3 });
        }
        if (state === "typing" || state === "typingEmail") typeField(0, "chris.walker@example.com");
        if (state === "typingPassword") typeField(1, "•••••••••••");
        if (state === "swiped" || state === "reset") {
          clearTyping();
          fields.forEach(field => { field.text.textContent = ""; });
        }
        card.dataset.demoTourState = state;
      };
      const initialize = () => {
        if (initialized) return;
        initialized = true;
        fields.forEach(field => field.field.replaceChildren(field.text, ...(field.caret ? [field.caret] : [])));
        targets.forEach(target => {
          const defaults: MotionState = {};
          Object.values(target.states).forEach(state => {
            if ("opacity" in state) defaults.opacity = 1;
            if ("scale" in state) defaults.scale = 1;
            if ("x" in state) defaults.x = 0;
            if ("y" in state) defaults.y = 0;
          });
          motionTo(target.element, { ...defaults, ...target.initial }, { duration: 0 });
        });
        if (cursor && cursorSpec) motionTo(cursor, { transform: cursorSpec.initial }, { duration: 0 });
        update();
      };
      const schedule = () => {
        const nextIndex = (stateIndex + 1) % states.length;
        timer = setTimeout(() => {
          stateIndex = nextIndex;
          update();
          schedule();
        }, spec.timings[states[nextIndex]]);
      };
      return [{
        name,
        start: () => { if (timer === null) { initialize(); schedule(); } },
        pause: () => { if (timer !== null) clearTimeout(timer); timer = null; clearTyping(); },
        cleanup: () => {
          if (timer !== null) clearTimeout(timer);
          clearTyping();
          fields.forEach(field => field.field.replaceChildren(...field.originals));
        },
      }];
    });
    const preparedTemplates = new Map<number, HTMLTemplateElement>();
    const getTemplate = (index: number) => {
      let template = preparedTemplates.get(index);
      if (!template) {
        template = document.createElement("template");
        template.innerHTML = advancedTourMarkup[index];
        template.content.querySelectorAll<SVGElement>("svg[data-tour-svg]").forEach(svg => {
          svg.innerHTML = advancedTourSvgs[svg.dataset.tourSvg || ""] || "";
        });
        preparedTemplates.set(index, template);
      }
      return template.content;
    };
    const sameNode = (current: Node, desired: Node): boolean => {
      if (current.nodeType !== desired.nodeType) return false;
      if (!(current instanceof Element) || !(desired instanceof Element)) return true;
      if (current.tagName !== desired.tagName) return false;
      const currentKey = current.getAttribute("data-tour-node");
      const desiredKey = desired.getAttribute("data-tour-node");
      return currentKey || desiredKey ? currentKey === desiredKey : current.getAttribute("class") === desired.getAttribute("class");
    };
    const animateNumber = (element: HTMLElement, before: string, after: string, enabled: boolean) => {
      if (before === after) return;
      element.classList.add("aurora-demo-number");
      element.setAttribute("data-tour-value", after);
      element.setAttribute("aria-label", after);
      element.replaceChildren(...Array.from(after).map((character, index) => {
        const digit = document.createElement("span");
        const previous = before[index];
        if (!/\d/.test(character) || !previous || !/\d/.test(previous) || character === previous || !enabled || reducedMotion.matches) {
          digit.textContent = character;
          return digit;
        }
        digit.className = "aurora-demo-digit is-spinning";
        digit.style.setProperty("--current", character);
        for (let value = 0; value < 10; value += 1) {
          const glyph = document.createElement("span");
          glyph.textContent = String(value);
          glyph.style.setProperty("--n", String(value));
          glyph.toggleAttribute("inert", String(value) !== character);
          digit.append(glyph);
        }
        const playback = digit.animate({ "--aurora-demo-digit-d": [Number(previous) - Number(character), 0] }, { duration: 900, easing: numberSpinEasing });
        const controls = { stop: () => playback.cancel() };
        runningAnimations.add(controls);
        playback.finished.then(() => {
          digit.classList.remove("is-spinning");
          runningAnimations.delete(controls);
        }, () => runningAnimations.delete(controls));
        return digit;
      }));
    };
    const morphChildren = (parent: Node, desired: Node) => {
      let position = 0;
      for (const next of Array.from(desired.childNodes)) {
        let current: Node | undefined = parent.childNodes[position];
        if (!current || !sameNode(current, next)) {
          const matching = Array.from(parent.childNodes).slice(position + 1).find(node => sameNode(node, next));
          current = matching || next.cloneNode(true);
          parent.insertBefore(current, parent.childNodes[position] || null);
        }
        if (current instanceof Element && next instanceof Element) {
          const animated = !!next.getAttribute("data-tour-node");
          const numberBefore = current.hasAttribute("data-tour-number") ? current.getAttribute("data-tour-value") || current.textContent || "" : null;
          const typed = current.hasAttribute("data-tour-typed");
          Array.from(current.attributes).forEach(({ name }) => {
            if ((animated && name === "style") || (typed && name === "data-tour-typed") || (numberBefore !== null && (name === "data-tour-value" || name === "aria-label"))) return;
            if (!next.hasAttribute(name)) current.removeAttribute(name);
          });
          Array.from(next.attributes).forEach(({ name, value }) => {
            if (!(animated && name === "style")) current.setAttribute(name, value);
          });
          if (numberBefore !== null && current instanceof HTMLElement) {
            animateNumber(current, numberBefore, next.textContent || "", next.getAttribute("data-tour-number-animated") !== "false");
          } else if (!typed) morphChildren(current, next);
        } else if (current.nodeValue !== next.nodeValue) current.nodeValue = next.nodeValue;
        position += 1;
      }
      while (parent.childNodes.length > position) parent.removeChild(parent.lastChild!);
    };
    const advancedTours = foregroundCards.flatMap(({ card, name }) => {
      if (!advancedTourData[name]) return [];
      let billing = false;
      let spec = advancedTourData[name];
      let stateIndex = 0;
      let timer: ReturnType<typeof setTimeout> | null = null;
      let shell: HTMLDivElement | null = null;
      let currentTemplate = -1;
      const originalChildren = Array.from(card.childNodes);
      const previous = new Map<string, { element: Element; animation: string }>();
      const typingTimers = new Set<ReturnType<typeof setTimeout>>();
      const clearTyping = () => { typingTimers.forEach(clearTimeout); typingTimers.clear(); };
      const renderFrame = (instant = false) => {
        if (!shell) {
          shell = document.createElement("div");
          shell.className = "aurora-demo-tour-shell";
          originalChildren.forEach(node => { if (node.parentNode === card) card.removeChild(node); });
          card.append(shell);
        }
        const state = Object.keys(spec.timings)[stateIndex];
        const frame = spec.frames[state];
        const templateIndex = spec.templates[frame.template];
        if (currentTemplate !== templateIndex) {
          morphChildren(shell, getTemplate(templateIndex));
          currentTemplate = templateIndex;
        }
        for (const [id, config] of Object.entries(frame.animations)) {
          const element = shell.querySelector<Element>(`[data-tour-node="${id}"]`);
          if (!element) continue;
          const last = previous.get(id);
          const value = JSON.stringify(config.animate);
          if (last?.element !== element) motionTo(element, config.initial, { duration: 0 });
          if (last?.element !== element || last.animation !== value) {
            motionTo(element, config.animate, instant ? { duration: 0, delay: 0 } : config.transition);
          }
          previous.set(id, { element, animation: value });
        }
        if (name === "CreateOrganization") {
          const placeholders = Array.from(shell.querySelectorAll<HTMLElement>("span.absolute")).filter(element => element.textContent === "Organization name" || element.textContent === "my-org");
          const fields = placeholders.map(element => element.nextElementSibling as HTMLElement).filter(Boolean);
          if (state === "typingName") {
            clearTyping();
            fields.forEach((field, index) => {
              const caret = field.querySelector('span[class*="top-[0.1em]"]');
              const typed = document.createElement("span");
              typed.className = "inline-block text-gray-950";
              field.setAttribute("data-tour-typed", "");
              field.replaceChildren(typed, ...(caret ? [caret] : []));
              const value = index === 0 ? "Test Organization" : "test-organization";
              Array.from(value).forEach((_, character) => {
                const typingTimer = setTimeout(() => {
                  typed.textContent = value.slice(0, character + 1);
                  typingTimers.delete(typingTimer);
                }, character * 60);
                typingTimers.add(typingTimer);
              });
            });
          } else if (state === "swipe") fields.forEach(field => {
            const typed = field.querySelector(".inline-block.text-gray-950");
            if (typed) motionTo(typed, { opacity: 0 }, { duration: 0.2, delay: 0.3 });
          });
          else if (state === "reset") {
            clearTyping();
            fields.forEach(field => { field.querySelector(".inline-block.text-gray-950")?.remove(); });
          }
        }
        card.dataset.demoTourState = state;
      };
      const schedule = () => {
        const states = Object.keys(spec.timings);
        const next = (stateIndex + 1) % states.length;
        timer = setTimeout(() => {
          stateIndex = next;
          renderFrame();
          schedule();
        }, spec.timings[states[next]]);
      };
      return [{
        name,
        select: (showBilling: boolean) => {
          const nextBilling = showBilling && !!advancedTourData[name + "Billing"];
          if (billing !== nextBilling) {
            if (timer !== null) clearTimeout(timer);
            timer = null;
            billing = nextBilling;
            spec = advancedTourData[name + (billing ? "Billing" : "")];
            stateIndex = 0;
            previous.clear();
          }
          renderFrame(true);
        },
        start: () => { if (timer === null) { renderFrame(true); schedule(); } },
        pause: () => { if (timer !== null) clearTimeout(timer); timer = null; clearTyping(); },
        cleanup: () => {
          if (timer !== null) clearTimeout(timer);
          clearTyping();
          shell?.remove();
          originalChildren.forEach(node => card.append(node));
        },
      }];
    });
    const tours = [...basicTours, ...advancedTours];
    const synchronizeTours = () => tours.forEach(tour => {
      if (inView && !smallScreen.matches && !reducedMotion.matches && tour.name === selectedDemo) tour.start();
      else tour.pause();
    });
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      inView = entry.isIntersecting;
      synchronizeTours();
    });
    visibilityObserver.observe(root);
    listen(smallScreen, "change", synchronizeTours);
    listen(reducedMotion, "change", synchronizeTours);
    cleanups.push(() => {
      visibilityObserver.disconnect();
      tours.forEach(tour => tour.cleanup());
      runningAnimations.forEach(animation => animation.stop());
    });

    const select = (button: HTMLButtonElement) => {
      const name = componentName(button);
      if (!name) return;
      const billing = /Billing/.test(button.textContent || "");
      selectedDemo = name;
      root.scrollLeft = 0;
      advancedTours.find(tour => tour.name === name)?.select(billing);
      synchronizeTours();
      const [x, y, mobileX, mobileY] = demoPositions[name];
      tracks.forEach(track => {
        track.style.setProperty("--x", `${-(x / 720 * 100)}%`);
        track.style.setProperty("--y", `${-(y / 602 * 100)}%`);
        track.style.setProperty("--x-mob", `${-(mobileX / 360 * 100)}%`);
        track.style.setProperty("--y-mob", `${-(mobileY / 602 * 100)}%`);
      });
      disclosures.forEach(disclosure => disclosure.buttons.forEach(item => {
        const active = item === button;
        item.classList.toggle("text-purple-500", active);
        item.classList.toggle("text-gray-950", !active);
        item.classList.toggle("hover:text-gray-600", !active);
        item.setAttribute("aria-pressed", String(active));
        const icon = item.querySelector("span.flex");
        if (icon) {
          icon.classList.toggle("text-purple-500", active);
          icon.classList.toggle("text-[#9394A1]", !active);
        }
      }));
      root.querySelectorAll<HTMLElement>("[data-demo-card], [data-demo-image]").forEach(card => {
        const active = (card.dataset.demoCard || card.dataset.demoImage) === name;
        const masked = maskTrack.contains(card);
        remember(card);
        card.classList.toggle("opacity-0", masked ? active : !active);
        card.classList.toggle("delay-300", active);
      });
      const activeCard = foregroundCards.find(item => item.name === name)?.card;
      if (activeCard && glowNodes.length) {
        if (advancedTourData[name]) initialCard?.prepend(...glowNodes);
        else activeCard.prepend(...glowNodes);
      }
      const mobileCard = Array.from(mobileTrack.querySelectorAll<HTMLElement>("[data-demo-image]")).find(card => card.dataset.demoImage === name && card.tagName !== "IMG" && getComputedStyle(card).display !== "none");
      if (mobileCard && mobileGlow) mobileCard.prepend(mobileGlow);

    };

    const expand = (selected: typeof disclosures[number]) => {
      disclosures.forEach(disclosure => {
        const expanded = disclosure === selected;
        const { trigger, panel } = disclosure;
        trigger.disabled = expanded;
        trigger.toggleAttribute("data-disabled", expanded);
        trigger.setAttribute("aria-expanded", String(expanded));
        trigger.classList.toggle("pb-2", expanded);
        trigger.classList.toggle("pb-4", !expanded);
        trigger.classList.toggle("text-gray-950", expanded);
        trigger.classList.toggle("text-gray-500", !expanded);
        trigger.classList.toggle("hover:text-gray-950", !expanded);
        trigger.parentElement?.parentElement?.toggleAttribute("data-expanded", expanded);
        const dot = trigger.querySelector("span");
        dot?.classList.toggle("bg-purple-500", expanded);
        dot?.classList.toggle("ring-1", !expanded);
        dot?.classList.toggle("ring-gray-400", !expanded);
        trigger.querySelector("svg")?.classList.toggle("rotate-180", expanded);
        panel.setAttribute("aria-hidden", String(!expanded));
        panel.inert = !expanded;
        panel.classList.toggle("grid-rows-[1fr]", expanded);
        panel.classList.toggle("grid-rows-[0fr]", !expanded);
        panel.classList.toggle("opacity-0", !expanded);
      });
      if (selected.buttons[0]) select(selected.buttons[0]);
    };

    disclosures.forEach(disclosure => {
      listen(disclosure.trigger, "click", () => expand(disclosure));
      disclosure.buttons.forEach(button => listen(button, "click", () => select(button)));
      listen(disclosure.trigger, "keydown", (event) => {
        const key = (event as KeyboardEvent).key;
        if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(key)) return;
        event.preventDefault();
        const available = disclosures.filter(item => !item.trigger.disabled);
        const index = available.indexOf(disclosure);
        const targetIndex = key === "Home" ? 0 : key === "End" ? available.length - 1 : (index + (key === "ArrowDown" ? 1 : -1) + available.length) % available.length;
        available[targetIndex]?.trigger.focus();
      });
    });

    // Native focus must not pan the clipped mosaic container.
    listen(root, "scroll", () => { if (root.scrollLeft) root.scrollLeft = 0; });

    const initialButton = disclosures.flatMap(({ buttons }) => buttons).find(button => button.classList.contains("text-purple-500"));
    if (initialButton) select(initialButton);
    root.dataset.componentGallery = "ready";

    return () => {
      cleanups.reverse().forEach(cleanup => cleanup());
      originalAttributes.forEach((attributes, element) => {
        Array.from(element.attributes).forEach(({ name }) => element.removeAttribute(name));
        attributes.forEach(([name, value]) => element.setAttribute(name, value));
      });
    };
  }, []);

  return null;
}

export default ComponentDemos;

